INSERT INTO names (name, root, gender, meaning, description, native_script, pronunciation, popularity) VALUES
('Suleyman', 'arabic', 'boy', 'man of peace, the prophet-king Solomon', 'Arabic Sulayman, the prophet and king known for wisdom, justice and power over wind and speech. Beloved across Arabic and Turkish cultures alike.', 'سليمان', 'soo-LAY-mahn', 78),
('Mustafa', 'arabic', 'boy', 'the chosen one', 'An honored title of the Prophet Muhammad, meaning "the chosen". Widely used across the Muslim world.', 'مصطفى', 'moos-TAH-fah', 80),
('Hamza', 'arabic', 'boy', 'strong, steadfast, lion', 'Name of the Prophet''s brave uncle Hamza ibn Abdul-Muttalib, a symbol of courage. Also the name of an Arabic letter.', 'حمزة', 'HAHM-zah', 75),
('Othman', 'arabic', 'boy', 'wise and generous serpent-bird, symbol of wisdom', 'Name of the third caliph Uthman ibn Affan, known for generosity and compiling the Quran.', 'عثمان', 'oth-MAHN', 65),
('Kareem', 'arabic', 'boy', 'generous, noble-hearted', 'From the divine attribute al-Kareem, "the Most Generous". A warm name for a kind soul.', 'كريم', 'kah-REEM', 76),
('Nasir', 'arabic', 'boy', 'helper, protector, supporter', 'From nasara, "to aid and defend". A name that promises protection.', 'ناصر', 'nah-SEER', 62),
('Nabil', 'arabic', 'boy', 'noble, distinguished', 'From nabaha, "to be elevated in character". Carries dignity and refinement.', 'نبيل', 'nah-BEEL', 58),
('Idris', 'arabic', 'boy', 'interpreter, studious one', 'Name of a prophet in the Quran, described as "a truthful man, a prophet". Also associated with learning and writing.', 'إدريس', 'id-REES', 60),
('Nuh', 'arabic', 'boy', 'peace, rest, the prophet Noah', 'The Quranic prophet who built the ark. A short, timeless name of patience and faith.', 'نوح', 'nooh', 55),
('Musa', 'arabic', 'boy', 'saved from the water, the prophet Moses', 'The Quranic prophet raised in Pharaoh''s palace who led his people to freedom.', 'موسى', 'moo-SAH', 64),
('Isa', 'arabic', 'boy', 'God is salvation, the prophet Jesus', 'The Quranic name of Prophet Jesus, honored as a messenger of God in Islam.', 'عيسى', 'ee-SAH', 58),
('Zayn', 'arabic', 'boy', 'beauty, grace', 'From zayn or zaynab root, "adornment and beauty". Modern-sounding yet classical.', 'زين', 'zayn', 70),
('Anas', 'arabic', 'boy', 'friendliness, congenial company', 'From uns, "warmth of company". Name of the young companion Anas ibn Malik who served the Prophet.', 'أنس', 'AH-nas', 57),
('Ziyad', 'arabic', 'boy', 'growth, abundance, increase', 'From zada, "to grow and multiply". A wish for a life of plenty.', 'زياد', 'zee-YAHD', 54),
('Rami', 'arabic', 'boy', 'archer, one who aims true', 'From ramaa, "to aim and shoot". Also the white gazelle in Arabic poetry.', 'رامي', 'RAH-mee', 56),
('Jamal', 'arabic', 'boy', 'beauty, grace', 'Directly means "beauty" in Arabic. A classic mid-century favorite still going strong.', 'جمال', 'jah-MAHL', 59),
('Saif', 'arabic', 'boy', 'sword of justice', 'Means "sword"; famously Saif al-Din, "sword of the faith". Sharp and noble.', 'سيف', 'sah-EEF', 60),
('Amin', 'arabic', 'boy', 'trustworthy, honest, faithful', 'The title given to the Prophet before his prophethood, "the Trustworthy". A name of integrity.', 'أمين', 'ah-MEEN', 61),
('Fahad', 'arabic', 'boy', 'leopard, swift wild cat', 'The Arabian leopard — a symbol of speed, strength and grace.', 'فهد', 'FAH-had', 62),
('Yazid', 'arabic', 'boy', 'increase, abundance', 'From zada, "to add and grow". Historic Umayyad name meaning growth.', 'يزيد', 'YAH-zeed', 48),
('Mansour', 'arabic', 'boy', 'victorious, aided by God', 'From nasara, "given victory". A confident, triumphant name.', 'منصور', 'man-SOOR', 55),
('Basel', 'arabic', 'boy', 'brave, valiant lion', 'From basala, "to be courageous". Historic name of Muslim commanders of Spain.', 'باسل', 'BAH-sel', 52),
('Hakim', 'arabic', 'boy', 'wise, judicious, healer', 'From the divine attribute al-Hakeem, "the All-Wise". Also means physician.', 'حكيم', 'hah-KEEM', 54),
('Faisal', 'arabic', 'boy', 'decisive judge, one who separates truth from falsehood', 'From fassala, "to judge between". Name of kings — strength of judgment.', 'فيصل', 'fay-SAHL', 63),
('Marwan', 'arabic', 'boy', 'flint stone, resilient', 'Name of a hard, bright stone used to kindle fire. Historic Umayyad name.', 'مروان', 'mar-WAHN', 57),
('Waleed', 'arabic', 'boy', 'newborn child', 'From walada, "to give birth". Celebrates the newborn itself.', 'وليد', 'wah-LEED', 58),
